package io.fireflysoftware.domain.accounting.web.posting;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import io.fireflysoftware.domain.accounting.core.posting.*;
import io.fireflysoftware.domain.accounting.core.posting.impl.ManagedPostingServiceImpl;
import io.fireflysoftware.domain.accounting.web.posting.impl.ManagedPostingExceptionHandlerImpl;
import java.time.Instant;
import java.util.UUID;
import org.fireflyframework.cqrs.command.CommandBus;
import org.junit.jupiter.api.Test;
import org.springframework.http.*;
import org.springframework.test.web.reactive.server.WebTestClient;
import reactor.core.publisher.Mono;
/** Controller-only HTTP contract; native JWT/exchange and default security are verified separately. */
class ManagedPostingHttpContractTest {
    static final UUID ACTION=new UUID(0,3);
    static final String DIGEST="a".repeat(64),BASE="/api/v1/tenants/"+new UUID(0,1)+"/books/"+new UUID(0,2)+"/ledger-journals";
    WebTestClient client(ManagedPostingService service){return WebTestClient.bindToController(new ManagedLedgerPostingsController(service)).controllerAdvice(new ManagedPostingExceptionHandlerImpl()).build();}
    WebTestClient.RequestHeadersSpec<?> request(WebTestClient client,boolean recovery,String body){return client.post().uri(BASE+(recovery?"/recovery":"")).header(HttpHeaders.AUTHORIZATION,"Bearer aaa.bbb.ccc").contentType(MediaType.APPLICATION_JSON).bodyValue(body);}
    ManagedPostingResponse result(ManagedPostingResponse.Status status,Integer ownerStatus){return new ManagedPostingResponse(ACTION,DIGEST,status,ownerStatus,null);}
    @Test void absentBearerHasFixedPreDispatchEnvelopeAndCannotInvokeService(){var service=mock(ManagedPostingService.class);client(service).post().uri(BASE).contentType(MediaType.APPLICATION_JSON).bodyValue("{}").exchange().expectStatus().isUnauthorized().expectHeader().valueEquals(HttpHeaders.CACHE_CONTROL,"no-store").expectBody().jsonPath("$.phase").isEqualTo("PRE_DISPATCH").jsonPath("$.code").isEqualTo("MANAGED_POSTING_PRE_DISPATCH_REJECTED").jsonPath("$.status").isEqualTo(401).jsonPath("$.actionId").doesNotExist();verifyNoInteractions(service);}
    @Test void malformedBearerCannotInvokeService(){var service=mock(ManagedPostingService.class);client(service).post().uri(BASE).header(HttpHeaders.AUTHORIZATION,"Bearer malformed").contentType(MediaType.APPLICATION_JSON).bodyValue("{}").exchange().expectStatus().isUnauthorized().expectBody().jsonPath("$.phase").isEqualTo("PRE_DISPATCH");verifyNoInteractions(service);}
    @Test void realStrictFacadeRejectsBeforeCqrsWithDocumentedEnvelope(){var bus=mock(CommandBus.class);request(client(new ManagedPostingServiceImpl(bus)),false,"{}").exchange().expectStatus().isBadRequest().expectBody().jsonPath("$.phase").isEqualTo("PRE_DISPATCH").jsonPath("$.status").isEqualTo(400).jsonPath("$.actionId").doesNotExist();verifyNoInteractions(bus);}
    @Test void unavailableAuthorityBeforeDispatchDoesNotClaimAnOwnerObservation(){var service=mock(ManagedPostingService.class);when(service.submit(anyString(),anyString(),any(),eq(false))).thenReturn(Mono.error(new ManagedPostingPreDispatchException(HttpStatus.SERVICE_UNAVAILABLE)));request(client(service),false,"{}").exchange().expectStatus().isEqualTo(503).expectBody().jsonPath("$.phase").isEqualTo("PRE_DISPATCH").jsonPath("$.status").isEqualTo(503).jsonPath("$.ownerStatus").doesNotExist();}
    @Test void everySupportedOwnerRefusalRetainsExactStatusAndOriginalCorrelation(){for(int status:new int[]{400,401,403,404,409,410,418,422,451}){var service=mock(ManagedPostingService.class);when(service.submit(anyString(),anyString(),any(),eq(false))).thenReturn(Mono.just(result(ManagedPostingResponse.Status.CURRENT_INVOCATION_REFUSED,status)));request(client(service),false,"{}").exchange().expectStatus().isEqualTo(status).expectHeader().valueEquals(HttpHeaders.CACHE_CONTROL,"no-store").expectBody().jsonPath("$.actionId").isEqualTo(ACTION.toString()).jsonPath("$.intentDigest").isEqualTo(DIGEST).jsonPath("$.status").isEqualTo("CURRENT_INVOCATION_REFUSED").jsonPath("$.ownerStatus").isEqualTo(status).jsonPath("$.phase").doesNotExist();verify(service,times(1)).submit(anyString(),anyString(),any(),eq(false));}}
    @Test void uncertainAndKnownCommitUnavailableRetainOriginalActionWithoutReceipt(){for(var status:new ManagedPostingResponse.Status[]{ManagedPostingResponse.Status.OUTCOME_UNKNOWN,ManagedPostingResponse.Status.COMMITTED_RESPONSE_UNAVAILABLE}){var service=mock(ManagedPostingService.class);when(service.submit(anyString(),anyString(),any(),eq(false))).thenReturn(Mono.just(result(status,null)));request(client(service),false,"{}").exchange().expectStatus().isEqualTo(503).expectBody().jsonPath("$.actionId").isEqualTo(ACTION.toString()).jsonPath("$.intentDigest").isEqualTo(DIGEST).jsonPath("$.status").isEqualTo(status.name()).jsonPath("$.phase").doesNotExist();}}
    @Test void missingRecoveryObservationPreservesActionAndRecoveryRoute(){var service=mock(ManagedPostingService.class);when(service.submit(anyString(),anyString(),any(),eq(true))).thenReturn(Mono.just(result(ManagedPostingResponse.Status.NOT_OBSERVED,404)));request(client(service),true,"{}").exchange().expectStatus().isNotFound().expectBody().jsonPath("$.actionId").isEqualTo(ACTION.toString()).jsonPath("$.status").isEqualTo("NOT_OBSERVED").jsonPath("$.ownerStatus").isEqualTo(404);verify(service,times(1)).submit(anyString(),anyString(),any(),eq(true));}
    @Test void committedReceiptIsTypedWithInstantAndNoStore(){var service=mock(ManagedPostingService.class);var receipt=new ManagedPostingReceipt(new UUID(0,4),ACTION,new UUID(0,5),1,DIGEST,false,Instant.parse("2026-11-01T12:00:00Z"));when(service.submit(anyString(),anyString(),any(),eq(false))).thenReturn(Mono.just(new ManagedPostingResponse(ACTION,DIGEST,ManagedPostingResponse.Status.COMMITTED,200,receipt)));request(client(service),false,"{}").exchange().expectStatus().isOk().expectHeader().valueEquals(HttpHeaders.CACHE_CONTROL,"no-store").expectBody().jsonPath("$.status").isEqualTo("COMMITTED").jsonPath("$.receipt.actionId").isEqualTo(ACTION.toString()).jsonPath("$.receipt.recordedAt").isEqualTo("2026-11-01T12:00:00Z");}
}
